--region init
function OverseaManageCatBallStarUpPopup:InitData()
    local parameters = self.controller.Argument.parameters
    local data = parameters.data

    ---@type CatEggDojo
    local catData   = data.catData
    ---@type MaidCoffeeCatRollConfigVo
    local vo        = data.vo
    self._catData   = catData
    
    self._maxStar   = MaidCoffeeUtils.CalcCatRollMaxStar()
    
    local star      = checkNumber(catData.star)
    local nextStar  = star + 1
    
    self._configVo   = vo
    self._originStar = star
    self._nextStar   = nextStar
    
    ---@type MaidCoffeeCatRollStarVo
    self._nextStarVo   = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(math.min(nextStar, self._maxStar))
    local starVo       = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(math.min(nextStar + 1, self._maxStar))
    
    self._lvLimit = self._nextStarVo.rank
    self._nextLvLimit = starVo.rank

    local skillId = vo.skillId
    self._mergeVo = QuestConfMgr:GetInstance():GetMergeSkillTypeVo(skillId)
    ---@type MaidCoffeeCatRollSkillGrowVo
    local originSkillGrowVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.skillId, star)
    ---@type QuestUpBuffVo
    self._originQuestBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(originSkillGrowVo.skillNumId)
    ---@type MaidCoffeeCatRollSkillGrowVo
    local nextSkillGrowVo = MaidCoffeeUtils.GetMaidCoffeeCatRollSkillGrowVo(vo.skillId, nextStar)
    ---@type QuestUpBuffVo
    self._nextQuestBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo( nextSkillGrowVo.skillNumId)
    
    local attributeType = self._originQuestBuffVo.attributeType
    self._attributeType = attributeType
    
    local consumes = self._nextStarVo.consumes
    self._generalConsumes, self._goldNum = GoodsUtils.SpiltGold(consumes)
    local catNum = self._nextStarVo.catNum
    table.insert(self._generalConsumes, {goodsId = vo.changeId, goodsNum = catNum})
end

function OverseaManageCatBallStarUpPopup:InitAction()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickBtnAction))
    SetButtonAction(self.BtnClose, Bind(self, self.OnClickBtnCloseAction))
end

--endregion


--region logic

function OverseaManageCatBallStarUpPopup:FreshUI()
    --- 刷新星级
    self:FreshStarGroup(self.BeforeStar, self._originStar)
    self:FreshStarGroup(self.AfterStar,  self._nextStar)
    
    self:FreshTitle()
    
    --- 刷新属性
    self.TextTitleAttr.text = self._mergeVo.desc

    if self._attributeType == Constants.QuestUpBufAttributeType.Attribute then
        ---@type BasicAttrAdditionVo
        local additionVo                = CardConfMgr:GetInstance():GetBasicAttrAdditionById(self._originQuestBuffVo.attributeId)
        local isConversion              = additionVo.isConversion
        self.TextNumberAttrBefore1.text = attribute_format(isConversion, self._originQuestBuffVo.addTypeNum)
        self.TextNumberAttrAfter1.text  = attribute_format(isConversion, self._nextQuestBuffVo.addTypeNum)
        
    elseif self._attributeType == Constants.QuestUpBufAttributeType.CombatEffectivenessConst then
        self.TextNumberAttrBefore1.text = self._originQuestBuffVo.combatValue1
        self.TextNumberAttrAfter1.text  = self._nextQuestBuffVo.combatValue1
        
    elseif self._attributeType == Constants.QuestUpBufAttributeType.CombatEffectivenessPercent then
        self.TextNumberAttrBefore1.text = attribute_format(1, self._originQuestBuffVo.combatValue2)
        self.TextNumberAttrAfter1.text  = attribute_format(1, self._nextQuestBuffVo.combatValue2)
        
    end
    
    --- 刷新等级上限
    self.TextNumberAttrBefore2.text = self._lvLimit
    self.TextNumberAttrAfter2.text  = self._nextLvLimit

    --- 刷新消耗道具
    UICommonUtils.FillCommonGoodsList(self.CommonGoodsList, self._generalConsumes, false, false, true, true)

    --- 刷新星运值
    self:FreshStarUpRate()
    
    --- 刷新升星成功率
    self:FreshSuccessRate()

    local isShowGold = self._goldNum > 0
    KTool.SetActive(self.CommonBtnConsumePop.gameObject, isShowGold)
    if isShowGold then
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, Constants.Currency.GoldId, self._goldNum)
    end
    
    
end

function OverseaManageCatBallStarUpPopup:FreshTitle()
    local env = CfUtils.GetLuaScr(self.CommonUITitleNode2, CommonUITitleNode)
    if env then
        env:Refresh(self._configVo.name)
    end
end

function OverseaManageCatBallStarUpPopup:FreshStarGroup(node, star)
    ---@type OverseaManageCatBallStarGroup
    local env = CfUtils.GetLuaScr(node, MaidCoffeeConstants.EnvPath.OverseaManageCatBallStarGroup)
    if not isNull(env) then
        env:FreshUI(star)
    end
end

function OverseaManageCatBallStarUpPopup:FreshStarUpRate()
    --self._catData.star
    local percent = math.min(1, self._catData.starUpRate)
    local starPointTips = string.format("%d%%", math.floor(percent * 100))
    self.TextNumberStarPoint.text = starPointTips
    self.Slider.value = percent
    
    
end

function OverseaManageCatBallStarUpPopup:FreshSuccessRate()
    self.TextNumberUpTips.text = string.format("%d%%", math.floor(checkNumber(self._nextStarVo.success) * 100)) 
    
end


