--region handler

function OverseaManageCatBallStarUpPopup:OnClickBtnAction()
    --if true then
    --    local playerCatId = self._catData.id
    --    ---@type CatEggComponent
    --    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    --    eggComponent:UpdateCatStarUp(playerCatId, 1, 0.1)
    --    CfUtils.DialogOpen(Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, {levelUpType = Constants.UICultivateLevelUpFinishType.CatBallStarUpSuccess, playerCatId = playerCatId, oldStar = 0}, nil, false)
    --    return
    --end
    
    local consumes = {
        {goodsId = Constants.Currency.GoldId, goodsNum = self._goldNum}
    }
    for i, v in ipairs(self._generalConsumes) do
        table.insert(consumes, v)
    end
    
    local realConsumes, errTips = GoodsUtils.CheckGoodConsume(consumes)
    if errTips then
        GameUtils.Toast(errTips)
        return
    end

    local playerCatId = self._catData.id
    local interface = Interfaces.MaidCoffeeCatStarUp
    local requestData = {playerCatId = playerCatId}
    GameUtils.Request(interface, requestData, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            local result = checkNumber(data.result)
            
            local oldStar = self._catData.star
            ---@type CatEggComponent
            local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
            eggComponent:UpdateCatStarUp(playerCatId, data.star, data.starUpRate)
            if checkNumber(data.star) == checkNumber(self._maxStar) then
                ---满星时需要更新基因数据
                local configVo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(self._catData.catId)
                if configVo then
                    local dojo = eggComponent:GetCat(playerCatId)
                    dojo.genes = configVo.kind2
                end
            end

            GoodsUtils.DrawRewards(realConsumes)
            Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, interface, requestData, self._generalConsumes)
            if result == 1 then
                CfUtils.DialogOpen(Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, {levelUpType = Constants.UICultivateLevelUpFinishType.CatBallStarUpSuccess, playerCatId = playerCatId, oldStar = oldStar}, nil, false)
                CfUtils.DialogClose(Constants.UITypeIds.OverseaManageCatballStarupPopup)
            else
                self._catData = eggComponent:GetCat(playerCatId)
                self:FreshStarUpRate()
                UICommonUtils.FillCommonGoodsList(self.CommonGoodsList, self._generalConsumes, false, false, true, true)
            end
            
        end
        
    end)
    
end

function OverseaManageCatBallStarUpPopup:OnClickBtnCloseAction()
    CfUtils.DialogClose(Constants.UITypeIds.OverseaManageCatballStarupPopup)
end

